@property --angle {
  syntax: '<angle>';
  initial-value: 0deg;
  inherits: false;
}

.gradient {
  background: conic-gradient(from var(--angle), red, blue);
  transition: --angle 1s;
}

.sidebar-layout {
  display: grid;
  grid-template-columns: 250px calc(100% - 250px);
}

.parent { position: relative; }
.child-a { position: absolute; z-index: 10; }
.child-b { position: absolute; z-index: 1; opacity: 0.9; }

.transformed { transform: translateX(0); z-index: 1; }
.normal { z-index: 999; }
/* .transformed is above .normal if .transformed comes last in DOM */

.grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0;
  margin: -8px;
}
.grid > * { padding: 8px; }

.item {
  flex: 1 1 200px; /* grow, shrink, basis */
}

.container {
  display: flex;
  flex-wrap: wrap;
  height: 400px;
  align-content: space-between;
  align-items: center;
}

.grid-center {
  display: grid;
  place-items: center;
}

.masonry {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-auto-flow: dense;
}

.layout {
  display: grid;
  grid-template:
    'header header' auto
    'sidebar main' 1fr
    'footer footer' auto
    / 200px 1fr;
}

.sticky-toast {
  position: fixed;
  bottom: 20px;
  right: 20px;
}

.overlay {
  position: absolute;
  inset: 0;
}

.article {
  contain: layout paint;
}

.off-screen-section {
  content-visibility: auto;
  contain-intrinsic-size: 0 500px;
}

text {
  fill: white;
  stroke: black;
  stroke-width: 4;
  paint-order: stroke fill;
}

.ball {
  offset-path: path('M 0 0 Q 200 200 400 0');
  animation: move 2s linear infinite;
}
@keyframes move {
  from { offset-distance: 0%; }
  to { offset-distance: 100%; }
}

.muted {
  color: color-mix(in srgb, var(--brand) 30%, white);
}
